import heapq
from typing import List, Dict, Any, Tuple

# ------------------------------------------------------------------
# Internal helper functions
# ------------------------------------------------------------------
def _parse_task_id(task_id: str) -> int:
    return int(task_id[1:])   # e.g. 'T001' → 1

def _parse_job_id(job_id: str) -> int:
    return int(job_id[1:])   # e.g. 'J01'  → 1

def _queue_key(task: Dict[str, Any]) -> Tuple[int, float, int]:
    """Sorting key for waiting queue: (-priority, submission, task id)."""
    return (-task["priority"], task["submission_time"], _parse_task_id(task["id"]))

# ------------------------------------------------------------------
# Core simulation routine – returns a list of outcome records
# ------------------------------------------------------------------
def _simulate_batch(doc: Dict[str, Any], scope: str,
                    inputs: List[Dict[str, Any]],
                    start: float, horizon: float) -> List[Dict[str, Any]]:
    """
    Run a forward simulation for one scope based solely on the supplied
    `inputs`.  The function records events that occur **after** `start`
    and **before** `horizon`.  The dependency on the original document
    is only for the node structures; all state is built from `inputs`.
    """
    # 1. Build machine specifications
    machines_spec: Dict[str, Any] = {}
    for inp in inputs:
        if inp["kind"] == "machine_spec":
            machines_spec[inp["id"]] = {
                "cpu": inp["fields"]["cpu"],
                "mem": inp["fields"]["memory"],
                "fails_at": inp["fields"]["fails_at"],
                "returns_at": inp["fields"]["returns_at"],
            }

    # 2. Build task submissions
    task_submissions: Dict[str, Any] = {}
    for inp in inputs:
        if inp["kind"] == "task_submission":
            task_id = inp["id"]
            task_submissions[task_id] = {
                "job": inp["fields"]["job"],
                "priority": inp["fields"]["priority"],
                "cpu": inp["fields"]["cpu"],
                "mem": inp["fields"]["memory"],
                "run_time": inp["fields"]["run_time"],
                "submission_time": inp["time"],
            }

    # 3. Initialise machine state
    machine_state: Dict[str, Any] = {}
    for mid, spec in machines_spec.items():
        machine_state[mid] = {
            "cpu": spec["cpu"],
            "mem": spec["mem"],
            "avail_cpu": spec["cpu"],
            "avail_mem": spec["mem"],
            "up": True,
            "fails_at": spec["fails_at"],
            "returns_at": spec["returns_at"],
            "running": {},          # task_id → runtime info
        }

    # 4. Queues & event heap
    waiting_queue: List[str] = []          # waiting task ids
    running_tasks: Dict[str, Any] = {}     # task_id → meta info

    events: List[Tuple[float, int, str, Any]] = []   # heap of (time, order, type, data)
    _event_order = 0

    def push_event(t: float, typ: str, data: Any):
        nonlocal _event_order
        heapq.heappush(events, (t, _event_order, typ, data))
        _event_order += 1

    # seed machine failure / return events
    for mid, spec in machines_spec.items():
        if spec["fails_at"] is not None:
            push_event(spec["fails_at"], "machine_fail", {"machine": mid})
        if spec["returns_at"] is not None:
            push_event(spec["returns_at"], "machine_return", {"machine": mid})

    # seed task submission events
    for tid, sub in task_submissions.items():
        push_event(sub["submission_time"], "task_submit", {"task_id": tid})

    # ------------------------------------------------------------------
    # Helper: start task immediately
    # ------------------------------------------------------------------
    def start_task(tid: str, mid: str, cur_time: float) -> List[Dict[str, Any]]:
        task = task_submissions[tid]
        res = [{
            "time": cur_time,
            "kind": "task_event",
            "entities": [tid, mid],
            "value": None,
            "src": None
        }]
        finish_time = cur_time + task["run_time"]
        push_event(finish_time, "task_finish", {"task_id": tid, "machine": mid})
        machine_state[mid]["avail_cpu"] -= task["cpu"]
        machine_state[mid]["avail_mem"] -= task["mem"]
        machine_state[mid]["running"][tid] = {
            "cpu": task["cpu"],
            "mem": task["mem"],
            "start_time": cur_time
        }
        running_tasks[tid] = {
            "machine": mid,
            "start_time": cur_time,
            "run_time": task["run_time"]
        }
        return res

    # ------------------------------------------------------------------
    # Helper: evict a free‑tier task (preemption or failure)
    # ------------------------------------------------------------------
    def evict_task(tid: str, mid: str, cur_time: float) -> List[Dict[str, Any]]:
        rt = machine_state[mid]["running"].pop(tid)
        machine_state[mid]["avail_cpu"] += rt["cpu"]
        machine_state[mid]["avail_mem"] += rt["mem"]
        running_tasks.pop(tid, None)
        res = [{
            "time": cur_time,
            "kind": "event_line",
            "entities": [mid, tid],
            "value": None,
            "src": None
        }]
        waiting_queue.append(tid)   # re‑queue at tail of waiting list
        return res

    # ------------------------------------------------------------------
    # Scheduling round – try to start every waiting task
    # ------------------------------------------------------------------
    def scheduling_round(cur_time: float):
        waiting_queue.sort(key=lambda tid: _queue_key(task_submissions[tid]))
        snapshot = list(waiting_queue)
        waiting_queue.clear()

        reservation_done = False   # only one reservation per round

        for tid in snapshot:
            task = task_submissions[tid]

            # 1. first‑fit
            placed = False
            for mid, m in sorted(machine_state.items()):
                if not m["up"]:
                    continue
                if m["avail_cpu"] >= task["cpu"] and m["avail_mem"] >= task["mem"]:
                    outcomes_all.extend(start_task(tid, mid, cur_time))
                    placed = True
                    break
            if placed:
                continue

            # 2. preemption – production task (priority ≥ 9) vs free‑tier
            if task["priority"] >= 9:
                for mid, m in sorted(machine_state.items()):
                    if not m["up"]:
                        continue
                    # free‑tier tasks currently running on this machine
                    free_tasks = [
                        (tid_ev, tr)
                        for tid_ev, tr in m["running"].items()
                        if task_submissions[tid_ev]["priority"] <= 1
                    ]
                    # order: lowest priority first, most recent start, higher id
                    free_tasks.sort(key=lambda x: (
                        task_submissions[x[0]]["priority"],
                        -x[1]["start_time"],
                        -_parse_task_id(x[0])
                    ))
                    avail_cpu, avail_mem = m["avail_cpu"], m["avail_mem"]
                    evict_list = []
                    for ftid, tr in free_tasks:
                        avail_cpu += tr["cpu"]
                        avail_mem += tr["mem"]
                        evict_list.append(ftid)
                        if avail_cpu >= task["cpu"] and avail_mem >= task["mem"]:
                            break
                    if avail_cpu >= task["cpu"] and avail_mem >= task["mem"]:
                        for ev_tid in evict_list:
                            outcomes_all.extend(evict_task(ev_tid, mid, cur_time))
                        outcomes_all.extend(start_task(tid, mid, cur_time))
                        placed = True
                        break
            if placed:
                continue

            # 3. reservation – only first unschedulable task
            if not reservation_done:
                best_time = None
                best_mid = None
                for mid, m in sorted(machine_state.items()):
                    if not m["up"]:
                        continue
                    # simulate future frees on this machine
                    finish_times = sorted(
                        [rt["start_time"] + task_submissions[tid_ev]["run_time"]
                         for tid_ev, rt in m["running"].items()]
                    )
                    avail_cpu, avail_mem = m["avail_cpu"], m["avail_mem"]
                    step = cur_time
                    if avail_cpu >= task["cpu"] and avail_mem >= task["mem"]:
                        best_time, best_mid = step, mid
                        break
                    for ft in finish_times:
                        # free tasks finishing at ft
                        for tid_ev, rt in list(m["running"].items()):
                            if rt["start_time"] + task_submissions[tid_ev]["run_time"] == ft:
                                avail_cpu += rt["cpu"]
                                avail_mem += rt["mem"]
                                m["running"].pop(tid_ev)
                        step = ft
                        if avail_cpu >= task["cpu"] and avail_mem >= task["mem"]:
                            best_time, best_mid = step, mid
                            break
                    if best_time is not None:
                        break
                reservation_done = True
                if best_time is not None:
                    push_event(best_time, "reserv_start",
                               {"task_id": tid, "machine": best_mid})
                waiting_queue.append(tid)
            else:
                waiting_queue.append(tid)

    # ------------------------------------------------------------------
    # Main simulation loop
    # ------------------------------------------------------------------
    outcomes_all: List[Dict[str, Any]] = []

    while events:
        t, _, typ, data = heapq.heappop(events)
        if t > horizon:
            break
        cur = t

        # gather all events at this exact moment
        batch = [(typ, data)]
        while events and events[0][0] == cur:
            _, _, typ2, data2 = heapq.heappop(events)
            batch.append((typ2, data2))

        # execution priority: finish → fail → return → submit → reserv_start
        order = {"task_finish": 0,
                 "machine_fail": 1,
                 "machine_return": 2,
                 "task_submit": 3,
                 "reserv_start": 4}
        batch.sort(key=lambda x: order.get(x[0], 9))

        for typ2, d2 in batch:
            if typ2 == "task_finish":
                if d2["task_id"] not in running_tasks:
                    continue
                # record finish only if after start
                if cur >= start:
                    outcomes_all.append({
                        "time": cur,
                        "kind": "task_event",
                        "entities": [d2["task_id"], d2["machine"]],
                        "value": None,
                        "src": None
                    })
                # free resources
                rt = machine_state[d2["machine"]]["running"].pop(d2["task_id"])
                machine_state[d2["machine"]]["avail_cpu"] += rt["cpu"]
                machine_state[d2["machine"]]["avail_mem"] += rt["mem"]
                running_tasks.pop(d2["task_id"], None)

            elif typ2 == "machine_fail":
                mid = d2["machine"]
                for tid in list(machine_state[mid]["running"].keys()):
                    if cur >= start:
                        outcomes_all.append({
                            "time": cur,
                            "kind": "task_event",
                            "entities": [tid, mid],
                            "value": None,
                            "src": None
                        })
                    outcomes_all.extend(evict_task(tid, mid, cur))
                machine_state[mid]["up"] = False
                machine_state[mid]["avail_cpu"] = 0
                machine_state[mid]["avail_mem"] = 0

            elif typ2 == "machine_return":
                mid = d2["machine"]
                machine_state[mid]["up"] = True
                machine_state[mid]["avail_cpu"] = machine_state[mid]["cpu"]
                machine_state[mid]["avail_mem"] = machine_state[mid]["mem"]

            elif typ2 == "task_submit":
                waiting_queue.append(d2["task_id"])

            elif typ2 == "reserv_start":
                tid = d2["task_id"]
                if tid in waiting_queue:
                    waiting_queue.remove(tid)
                    outcomes_all.extend(start_task(tid, d2["machine"], cur))

        # perform grow‑internal scheduling round after all events at this time
        scheduling_round(cur)

    # keep only outcomes between start and horizon
    outcomes_all = [o for o in outcomes_all if o["time"] is not None and a <= o["time"] <= rooth for a in [start] for rooth in [horizon]]
    outcomes_all.sort(key=lambda r: (r["time"], r["kind"]))
    return outcomes_all

# ------------------------------------------------------------------
# Public API – the function required by the exercise
# ------------------------------------------------------------------
def simulate(doc: Dict[str, Any], scope: str,
             inputs: List[Dict[str, Any]],
             params: Dict[str, Any],
             start: float = None,
             horizon: float = None) -> List[Dict[str, Any]]:
    """
    Forward model of the scheduling process for the given scope.

    Parameters
    ----------
    doc     : full parsed document (unused after initial processing)
    scope   : title of the scope to simulate
    inputs  : list produced by inputs()
    params  : constant parameters (unused in current model)
    start   : simulation start time (default earliest input)
    horizon : simulation horizon time (default latest input)

    Returns
    -------
    List[Dict[str, Any]] – outcome records in the same shape as outcomes()
    """
    # default boundary values
    if start is None:
        start = 0.0
    if horizon is None:
        horizon = None
        for inp in inputs:
            if inp["time"] is not None:
                t = float(inp["time"])
                if horizon is None or t > horizon:
                    horizon = t
        if horizon is None:
            horizon = 0.0

    return _simulate_batch(doc, scope, inputs, start, horizon)

